import numpy as np

def solve():
    solutions = []
    # Grid search
    for x in np.linspace(-1.732, 1.732, 500):
        for y in np.linspace(-1.732, 1.732, 500):
            z2 = 3 - x**2 - y**2
            if z2 >= 0:
                z = np.sqrt(z2)
                # Check z
                if abs(x*y**3 + y*z**3 + z*x**3 - 3) < 1e-3:
                    solutions.append((x, y, z))
                # Check -z
                z_neg = -z
                if abs(x*y**3 + y*z_neg**3 + z_neg*x**3 - 3) < 1e-3:
                    solutions.append((x, y, z_neg))

    # Filter unique solutions
    unique_solutions = []
    for sol in solutions:
        is_new = True
        for u_sol in unique_solutions:
            if np.allclose(sol, u_sol, atol=1e-2):
                is_new = False
                break
        if is_new:
            unique_solutions.append(sol)

    print(f"Number of unique solutions: {len(unique_solutions)}")
    for sol in unique_solutions:
        print(sol)

solve()

